import{_ as e,C as t,c as a,o as i,j as l,G as o,b as r,a0 as s,a as n,w as h,a1 as u}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"SMART Goals for Pétanque","description":"","frontmatter":{},"headers":[],"relativePath":"en/education/goals/smart-goals.md","filePath":"en/education/goals/smart-goals.md"}');const d=e({name:"en/education/goals/smart-goals.md"},[["render",function(e,c,d,g,m,p){const b=t("AdBanner"),f=t("Mermaid"),y=t("AdInArticle");return i(),a("div",null,[c[1]||(c[1]=l("h1",{id:"smart-goals-for-petanque",tabindex:"-1"},[n("SMART Goals for Pétanque "),l("a",{class:"header-anchor",href:"#smart-goals-for-petanque","aria-label":'Permalink to "SMART Goals for Pétanque"'},"​")],-1)),o(b),c[2]||(c[2]=l("p",null,"The SMART framework transforms vague wishes into actionable goals. Let's look at each element in detail, with specific examples for pétanque.",-1)),c[3]||(c[3]=l("div",{class:"tip custom-block"},[l("p",{class:"custom-block-title"},"The Big Idea"),l("p",null,[l("strong",null,"Vague goals lead to vague results."),n(' SMART goals create clarity, action, and measurable progress. Transform "I want to get better" into specific targets you can actually achieve.')])],-1)),(i(),r(u,null,{default:h(()=>[o(f,{id:"mermaid-13",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BVague%20Goal%5D%20--%3E%20B%5BNo%20Clear%20Action%5D%0A%20%20%20%20B%20--%3E%20C%5BNo%20Progress%5D%0A%0A%20%20%20%20D%5BSMART%20Goal%5D%20--%3E%20E%5BClear%20Action%20Plan%5D%0A%20%20%20%20E%20--%3E%20F%5BMeasurable%20Progress%5D%0A%20%20%20%20F%20--%3E%20G%5BAchievement%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffebee%0A%20%20%20%20style%20C%20fill%3A%23ffebee%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A%20%20%20%20style%20G%20fill%3A%23fff4e1%0A"})]),fallback:h(()=>[...c[0]||(c[0]=[n(" Loading... ",-1)])]),_:1})),c[4]||(c[4]=s('<h2 id="s-specific" tabindex="-1">S - Specific <a class="header-anchor" href="#s-specific" aria-label="Permalink to &quot;S - Specific&quot;">​</a></h2><p>A specific goal answers these questions:</p><ul><li><strong>What</strong> exactly do I want to achieve?</li><li><strong>Where</strong> will this happen?</li><li><strong>Which</strong> aspects are involved?</li></ul><h3 id="making-goals-specific" tabindex="-1">Making Goals Specific <a class="header-anchor" href="#making-goals-specific" aria-label="Permalink to &quot;Making Goals Specific&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Vague</th><th>Specific</th></tr></thead><tbody><tr><td>&quot;Improve my pointing&quot;</td><td>&quot;Improve my pointing accuracy on gravel surfaces at 7-9 meter distances&quot;</td></tr><tr><td>&quot;Get mentally stronger&quot;</td><td>&quot;Develop a consistent pre-shot routine that I use for every throw&quot;</td></tr><tr><td>&quot;Win more games&quot;</td><td>&quot;Win at least 60% of my competitive games this season&quot;</td></tr></tbody></table><h3 id="specificity-checklist" tabindex="-1">Specificity Checklist <a class="header-anchor" href="#specificity-checklist" aria-label="Permalink to &quot;Specificity Checklist&quot;">​</a></h3><ul><li>[ ] Can someone else understand exactly what I&#39;m trying to do?</li><li>[ ] Have I defined the conditions (distance, surface, situation)?</li><li>[ ] Is there only one interpretation of this goal?</li></ul><h2 id="m-measurable" tabindex="-1">M - Measurable <a class="header-anchor" href="#m-measurable" aria-label="Permalink to &quot;M - Measurable&quot;">​</a></h2><p>If you can&#39;t measure it, you can&#39;t manage it. Measurable goals let you track progress and know when you&#39;ve succeeded.</p><h3 id="ways-to-measure-petanque-goals" tabindex="-1">Ways to Measure Pétanque Goals <a class="header-anchor" href="#ways-to-measure-petanque-goals" aria-label="Permalink to &quot;Ways to Measure Pétanque Goals&quot;">​</a></h3><p><strong>Quantitative measures:</strong></p><ul><li>Points scored in drills (e.g., 24/30)</li><li>Percentage accuracy (e.g., 75% hit rate)</li><li>Distance from target (e.g., average 30cm from jack)</li><li>Consistency (e.g., 3 successful sessions in a row)</li></ul><p><strong>Using Training Drills as Measures:</strong></p><table tabindex="0"><thead><tr><th>Drill</th><th>What It Measures</th><th>Target Example</th></tr></thead><tbody><tr><td>Shooting Ladder</td><td>Shooting accuracy under pressure</td><td>Reach 10m within 30 boules</td></tr><tr><td>Pointing Precision</td><td>Pointing accuracy to zone</td><td>24/30 points</td></tr><tr><td>Distance Variation</td><td>Depth control</td><td>80% within 50cm</td></tr></tbody></table><h3 id="tracking-your-measurements" tabindex="-1">Tracking Your Measurements <a class="header-anchor" href="#tracking-your-measurements" aria-label="Permalink to &quot;Tracking Your Measurements&quot;">​</a></h3><p>Keep a simple log:</p><ul><li>Date</li><li>Drill/exercise</li><li>Score/result</li><li>Conditions (surface, weather)</li><li>Notes</li></ul><h2 id="a-achievable-but-challenging" tabindex="-1">A - Achievable (but Challenging) <a class="header-anchor" href="#a-achievable-but-challenging" aria-label="Permalink to &quot;A - Achievable (but Challenging)&quot;">​</a></h2><p>Goals should stretch you without being impossible.</p><h3 id="finding-the-right-level" tabindex="-1">Finding the Right Level <a class="header-anchor" href="#finding-the-right-level" aria-label="Permalink to &quot;Finding the Right Level&quot;">​</a></h3><p><strong>Too easy:</strong> &quot;Practice once this month&quot;</p><ul><li>No growth, no motivation</li></ul>',22)),o(y),c[5]||(c[5]=s('<p><strong>Too hard:</strong> &quot;Never miss a shot&quot;</p><ul><li>Impossible, leads to frustration</li></ul><p><strong>Just right:</strong> &quot;Improve shooting accuracy by 15% in 8 weeks&quot;</p><ul><li>Challenging but realistic with effort</li></ul><h3 id="questions-to-test-achievability" tabindex="-1">Questions to Test Achievability <a class="header-anchor" href="#questions-to-test-achievability" aria-label="Permalink to &quot;Questions to Test Achievability&quot;">​</a></h3><ul><li>Have others at my level achieved this?</li><li>Do I have the time and resources needed?</li><li>Is this within my control (mostly)?</li><li>Am I willing to do what it takes?</li></ul><h3 id="stretch-goals" tabindex="-1">Stretch Goals <a class="header-anchor" href="#stretch-goals" aria-label="Permalink to &quot;Stretch Goals&quot;">​</a></h3><p>It&#39;s okay to have ambitious long-term goals. Just make sure your short-term goals are achievable steps toward them.</p><h2 id="r-relevant" tabindex="-1">R - Relevant <a class="header-anchor" href="#r-relevant" aria-label="Permalink to &quot;R - Relevant&quot;">​</a></h2><p>Your goals should align with your bigger picture.</p><h3 id="relevance-questions" tabindex="-1">Relevance Questions <a class="header-anchor" href="#relevance-questions" aria-label="Permalink to &quot;Relevance Questions&quot;">​</a></h3><ul><li>Does this goal support my overall development?</li><li>Is this the right priority right now?</li><li>Does this fit with my available time and resources?</li><li>Am I genuinely motivated by this goal?</li></ul><h3 id="example-checking-relevance" tabindex="-1">Example: Checking Relevance <a class="header-anchor" href="#example-checking-relevance" aria-label="Permalink to &quot;Example: Checking Relevance&quot;">​</a></h3><p><strong>Situation:</strong> You want to compete at national level</p><p><strong>Relevant goals:</strong></p><ul><li>Improve shooting accuracy (directly impacts results)</li><li>Develop mental routines (helps in pressure situations)</li><li>Increase training frequency (builds skill faster)</li></ul><p><strong>Less relevant goals:</strong></p><ul><li>Learn trick shots (fun but not competitive priority)</li><li>Buy expensive new boules (equipment isn&#39;t your limiting factor)</li></ul><h2 id="t-time-bound" tabindex="-1">T - Time-bound <a class="header-anchor" href="#t-time-bound" aria-label="Permalink to &quot;T - Time-bound&quot;">​</a></h2><p>Deadlines create urgency and enable planning.</p><h3 id="setting-timeframes" tabindex="-1">Setting Timeframes <a class="header-anchor" href="#setting-timeframes" aria-label="Permalink to &quot;Setting Timeframes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Goal Type</th><th>Typical Timeframe</th></tr></thead><tbody><tr><td>Long-term</td><td>1-3 years</td></tr><tr><td>Annual</td><td>12 months</td></tr><tr><td>Quarterly</td><td>3 months</td></tr><tr><td>Monthly</td><td>4 weeks</td></tr><tr><td>Weekly</td><td>7 days</td></tr><tr><td>Session</td><td>Single practice</td></tr></tbody></table><h3 id="example-timeline" tabindex="-1">Example Timeline <a class="header-anchor" href="#example-timeline" aria-label="Permalink to &quot;Example Timeline&quot;">​</a></h3><p><strong>Long-term (2 years):</strong> Qualify for national team selection</p><p><strong>Annual:</strong> Finish top 10 in regional rankings</p><p><strong>Quarterly (Q1):</strong></p><ul><li>Establish consistent training routine</li><li>Improve shooting to 70% accuracy</li></ul><p><strong>Monthly (January):</strong></p><ul><li>Week 1: Assess current level, set baselines</li><li>Week 2-3: Focus on shooting technique</li><li>Week 4: Test and measure progress</li></ul><p><strong>Weekly:</strong></p><ul><li>Monday: Technical shooting session</li><li>Wednesday: Pointing and game situations</li><li>Friday: Mental training and visualization</li><li>Weekend: Competition or match practice</li></ul><h2 id="putting-it-all-together" tabindex="-1">Putting It All Together <a class="header-anchor" href="#putting-it-all-together" aria-label="Permalink to &quot;Putting It All Together&quot;">​</a></h2><h3 id="goal-setting-worksheet" tabindex="-1">Goal Setting Worksheet <a class="header-anchor" href="#goal-setting-worksheet" aria-label="Permalink to &quot;Goal Setting Worksheet&quot;">​</a></h3><p><strong>My Goal (first draft):</strong></p><hr><p><strong>Specific - What exactly?</strong></p><hr><p><strong>Measurable - How will I know?</strong></p><hr><p><strong>Achievable - Is it realistic?</strong></p><hr><p><strong>Relevant - Why does this matter?</strong></p><hr><p><strong>Time-bound - By when?</strong></p><hr><p><strong>My SMART Goal (final version):</strong></p><hr><h3 id="example-completed" tabindex="-1">Example Completed <a class="header-anchor" href="#example-completed" aria-label="Permalink to &quot;Example Completed&quot;">​</a></h3><p><strong>First draft:</strong> &quot;Get better at shooting&quot;</p><p><strong>SMART version:</strong> &quot;By April 30th, I will achieve a score of 24/30 or higher on the Shooting Ladder drill (6-10m with obstacles) in three consecutive training sessions, measured by my training log.&quot;</p><h2 id="key-takeaway" tabindex="-1">Key Takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to &quot;Key Takeaway&quot;">​</a></h2><blockquote><p>SMART goals turn dreams into plans and plans into results.</p></blockquote><p>Take time to craft your goals properly. A well-defined goal is half the journey.</p>',53)),o(b)])}]]);export{c as __pageData,d as default};
